// TH18 v1.00a Stage 3 MainSub04 (st03.ecl.txt:1182-1199) + Cir00 (st03.ecl.txt:6-76).
// 已批准：F 门奖励编队固定为完整独立波，17 轮 x 4 = 68 次计划创建全部保留。
const TIME_LIMIT: int = 1800; // 120 帧外壳缓冲 + 本段排程/发弹/尾弹局部估计
const TH18_BALL2: int = 432;  // 源 etSprite(0,5,4)

// 源 Cir00_at (st03.ecl.txt:28-75): 单发自机狙，20 帧间隔，3/3/8/9 轮。
// etEx(0,0,2,1,...) 的 ANIM 出生退位移保留为 -4*velocity（sh_dist 沿弹自身角度后推）。
async sub cir_fire() {
    var rank: int = global(GVAR_RANK);
    var delay: int = 10 + rand(40);   // 源 10 + ($RAND % 40)
    var shots: int = 8;
    var speed: fx = 2.2fx;
    if rank < 2 {
        delay = 10 + rand(200);        // 源 10 + ($RAND % 200)
        shots = 3;
        speed = 1.5fx;
    }
    if rank == 3 { shots = 9; speed = 3fx; }
    wait(delay);
    sh_reset(0);
    sh_sprite(0, TH18_BALL2, 4);       // etSprite(0,5,4)
    sh_aim(0, 1);                      // etAim(0,0)，N=1 退化为正对自机
    sh_count(0, 1, 1);                 // etCount(0,1,1)
    sh_angle(0, 0deg, 0deg);           // etAngle(0,0.0f,0.0f)
    sh_speed(0, speed, 0fx);           // etSpeed 的 M=1 取首速，1.0 为层步长不参与
    sh_dist(0, -4fx * speed);          // ANIM a=1: 出生位置 -= 4*velocity
    for i in 0..shots {
        sh_fire(0);
        wait(20);
    }
}

// 源 Cir00 (st03.ecl.txt:6-26): 出生框 28/16，moveVel(pi/2 + RANDF2*5deg, 2)，
// 再 moveEllipseRel(RANDRAD, 2deg, 60, 0, ABS_ANGLE, 0)；s=0 时 REL 为固定轴上的正弦偏移。
// 参数在创建处抽样后传入；父任务算好设置当帧的即时位置（θ 尚未推进）。
async sub cir00(bx: fx, by: fx, alpha: angle, theta0: angle) {
    set_invuln(65535);                 // 练习外壳：小敌不因 SHOT 退场
    set_hurtbox(14fx);                 // 源 setHurtbox(28,28)
    set_hitbox(8fx);                   // 源 setHitbox(16,16)
    var vx: fx = 2fx * cos(alpha);     // moveVel(alpha, 2.0)
    var vy: fx = 2fx * sin(alpha);
    var phase: angle = theta0;
    var t: int = 0;
    if global(GVAR_RANK) > 0 { spawn cir_fire(); } // !NHL 才启动 Cir00_at
    loop {
        var next_phase: angle = phase + 2deg; // ω=0.034906585 rad
        var s: fx = sin(next_phase - alpha);
        var next_x: fx = bx + vx * ((t + 1) as fx) - 60fx * s * sin(alpha);
        var next_y: fx = by + vy * ((t + 1) as fx) + 60fx * s * cos(alpha);
        move_vel_xy(0, next_x - $self_x, next_y - $self_y, EASE_LINEAR);
        phase = next_phase;
        t = t + 1;
        wait(1);
    }
}

// 源 MainSub04 的 4 次创建：每次独立抽 RANDF 作为 |x|，左右符号由创建行决定。
sub spawn_cir(sign: int) {
    var x: fx = (rand(1200) as fx) / 10fx;   // RANDF * 120（0.1px 分辨率）
    if sign < 0 { x = 0fx - x; }             // RANDF * -120
    var a: angle = 90deg + ((rand(1821) - 910) as angle); // RANDF2 * 5deg
    var th: angle = rand(65536) as angle;    // RANDRAD
    var s0: fx = sin(th - a);                // s=0 椭圆：设置当帧的 REL 偏移
    _ = spawn_enemy(x - 60fx * s0 * sin(a), -32fx + 60fx * s0 * cos(a),
                    150, 0, 0, 0, cir00(x, -32fx, a, th));
}

async sub wave() {
    wait(120);                         // 外壳开场缓冲
    for round in 0..17 {
        spawn_cir(1);  wait(17);
        spawn_cir(-1); wait(17);
        spawn_cir(1);  wait(17);
        spawn_cir(-1); wait(17);
    }
    loop { wait(600); }
}

async sub controller() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);  // 外壳控制敌关闭体碰
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 10000, 0, 0, 0, controller);
    loop { wait(600); }
}
